/**
 * ターゲットメソッド - 解析対象
 */
public String targetMethod(RequestData request, String param1, String param2) {
    SessionData session = request.getSession();
    DtoData dtoInfo = (DtoData) session.getAttribute("DTO_INFO");

    if (dtoInfo != null && dtoInfo.getId() != null) {
        try {
            // ★ このパターンが問題
            // 外側: serviceInstance.updateData(...) - 検出されるべき
            // 内側: getHelperMethod(request) - 検出される
            serviceInstance.updateData(session, dtoInfo, param2, getHelperMethod(request));
        } catch (Exception e) {
            session.removeAttribute("DTO_INFO");
            throw new RuntimeException("Error", e);
        }
    }
    return "redirect:" + param1;
}

